		return SuperpositionHandler.isTheCursedOne(player) && this.getLastDeathLocation(player) != null;
	}

private CompoundTag getLastDeathLocation(Player player) {
		return (CompoundTag) SuperpositionHandler.getPersistentTag(player, "LastDeathLocation", null);
	}

@Override
	public ItemStack finishUsingItem(ItemStack stack, Level worldIn, LivingEntity living) {
		if (living instanceof Player) {
			Player player =  (Player) living;

			this.onConsumed(worldIn, player, stack);

			if (player instanceof ServerPlayer) {
				CriteriaTriggers.CONSUME_ITEM.trigger((ServerPlayer) player, stack);
			}

			if (!player.getAbilities().instabuild) {
				stack.shrink(1);

				if (stack.isEmpty())
					return new ItemStack(Items.GLASS_BOTTLE);

				player.getInventory().add(new ItemStack(Items.GLASS_BOTTLE));
			}

		}

		return stack;
	}

@Override
	public InteractionResultHolder<ItemStack> use(Level worldIn, Player playerIn, InteractionHand handIn) {
		if (this.canDrink(worldIn, playerIn, playerIn.getItemInHand(handIn))) {
			playerIn.startUsingItem(handIn);
			return super.use(worldIn, playerIn, handIn);
		} else
			return new InteractionResultHolder<>(InteractionResult.PASS, playerIn.getItemInHand(handIn));
	}

