        EnumBestiaryPages[] pages = new EnumBestiaryPages[3];
        if (this.tileFurnace.getItem(0).getItem() == IafItemRegistry.BESTIARY.get()) {
            if (possiblePagesInt[0] < 0) {
                pages[0] = null;
